function TurnstileManager() {
  var widgetId = null;
  var isActive = 0;
  var renderStartTime = 0;
  var token = "";
  var tokenTime = 0;
  var scriptLoaded = 0;
  var containerElement = null;
  var overlayElement = null;
  var pendingRender = false;
  var retryCount = 0;
  var maxRetries = 3;
  var retryTimer = null;

  this.init = function () {
    if (gameState.testversion || platform.id > 0) {
      console.log("[ECHO] Turnstile skipped (testversion=" + gameState.testversion + ", platform.id=" + platform.id + ")");
      return;
    }
    if (window.turnstile) {
      scriptLoaded = 1;
      console.log("[ECHO] Turnstile already loaded");
      return;
    }
    console.log("[ECHO] Loading Cloudflare Turnstile script...");
    try {
      var script = document.createElement("script");
      script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit";
      script.async = true;
      script.onload = function () {
        scriptLoaded = 1;
        console.log("[ECHO] Turnstile script loaded successfully!");
        if (pendingRender) {
          console.log("[ECHO] Rendering pending Turnstile widget...");
          turnstileManager.renderTurnstile();
        }
      };
      script.onerror = function (e) {
        console.error("[ECHO] Turnstile script FAILED to load.");
      };
      document.head.appendChild(script);
    } catch (e) {
      console.error("[ECHO] Turnstile init exception: " + e);
    }
  };

  function showOverlay() {
    if (overlayElement) return;
    overlayElement = document.createElement("div");
    overlayElement.id = "echo-turnstile-container";
    overlayElement.style.position = "fixed";
    overlayElement.style.left = "0";
    overlayElement.style.top = "0";
    overlayElement.style.zIndex = "100";
    document.body.appendChild(overlayElement);
  }

  function hideOverlay() {
    if (overlayElement) {
      try { overlayElement.remove(); } catch (e) {}
      overlayElement = null;
    }
  }

  function updateStatus(msg) {
    var el = document.getElementById("echo-turnstile-status");
    if (el) el.textContent = msg;
  }

  this.renderTurnstile = function () {
    if (!scriptLoaded) {
      console.log("[ECHO] Turnstile render: script not loaded yet, queuing...");
      pendingRender = true;
      return false;
    }
    if (!window.turnstile) {
      console.log("[ECHO] Turnstile render: window.turnstile not available, queuing...");
      pendingRender = true;
      return false;
    }
    if (isActive) {
      console.log("[ECHO] Turnstile render: already active, skipping");
      return false;
    }
    if (isTokenValid(30)) {
      console.log("[ECHO] Turnstile: existing token still valid");
      return false;
    }
    if (retryCount >= maxRetries) {
      console.warn("[ECHO] Turnstile: max retries (" + maxRetries + ") exhausted.");
      updateStatus("Verification failed. See console for details.");
      return false;
    }
    retryCount++;
    token = "";
    isActive = 1;
    pendingRender = false;
    renderStartTime = performance.now();
    console.log("[ECHO] Turnstile render: attempt " + retryCount + "/" + maxRetries);
    showOverlay();
    updateStatus("Loading verification... (attempt " + retryCount + "/" + maxRetries + ")");
    containerElement = document.getElementById("echo-turnstile-container");
    try {
      widgetId = window.turnstile.render(containerElement, {
        sitekey: "0x4AAAAAAEI8HZoG8nJMzxt1",
        action: "enter_lobby",
        appearance: "interaction-only",
        callback: function (t) {
          console.log("[ECHO] Turnstile SUCCESS in " + Math.floor(performance.now() - renderStartTime) + "ms");
          token = t;
          tokenTime = performance.now();
          retryCount = 0;
          cleanupWidget();
          turnstileManager.sendTokenToLobby();
        },
        "expired-callback": function () {
          console.warn("[ECHO] Turnstile EXPIRED");
          cleanupWidget();
          scheduleRetry();
        },
        "error-callback": function (err) {
          console.error("[ECHO] Turnstile ERROR: " + err);
          cleanupWidget();
          scheduleRetry();
        }
      });
      console.log("[ECHO] Turnstile widget rendered, id=" + widgetId);
      updateStatus("Please complete the verification above");
    } catch (e) {
      console.error("[ECHO] Turnstile render exception: " + e);
      cleanupWidget();
      scheduleRetry();
    }
    return true;
  };

  function scheduleRetry() {
    if (retryCount >= maxRetries) {
      console.warn("[ECHO] Turnstile: all retries exhausted");
      updateStatus("Verification failed after " + maxRetries + " attempts. Sitekey requires territorial.io domain.");
      return;
    }
    var delay = 5000;
    console.log("[ECHO] Retrying Turnstile in " + delay + "ms (attempt " + (retryCount + 1) + "/" + maxRetries + ")...");
    updateStatus("Failed, retrying in " + (delay / 1000) + "s... (" + (retryCount + 1) + "/" + maxRetries + ")");
    retryTimer = setTimeout(function () {
      turnstileManager.renderTurnstile();
    }, delay);
  }

  function cleanupWidget() {
    if (retryTimer) { clearTimeout(retryTimer); retryTimer = null; }
    if (containerElement === null || widgetId === null) {
      hideOverlay();
      return;
    }
    isActive = 0;
    try { window.turnstile.remove(widgetId); } catch (e) {}
    containerElement.innerHTML = "";
    containerElement = null;
    widgetId = null;
    hideOverlay();
  }

  this.sendTokenToLobby = function () {
    if (!isTokenValid(8)) {
      console.log("[ECHO] sendTokenToLobby: no valid token");
      return;
    }
    if (!lobbyManager.isInitialized) {
      console.log("[ECHO] sendTokenToLobby: lobby not initialized yet");
      return;
    }
    if (!networkManager.connectionManager.isOpen(networkManager.connectionManager.currentLobby)) {
      console.log("[ECHO] sendTokenToLobby: lobby connection not open");
      return;
    }
    console.log("[ECHO] sendTokenToLobby SUCCESS!");
    networkManager.responsePacketBuilder.sendTurnstileToken(token);
    token = "";
  };

  function isTokenValid(expirySeconds) {
    return token !== "" && (tokenTime + 1000 * (60 * 5 - expirySeconds)) > performance.now();
  }
}
